c.python:
SELECT SUM(
    LEAST(
        (SELECT MAX(height) FROM Heights a WHERE a.id <= h.id),
        (SELECT MAX(height) FROM Heights b WHERE b.id >= h.id)
    ) - h.height
) AS total_trapped_water
FROM Heights h;

